main_section_html:
{%- set _co = frappe.get_all('Company', fields=['default_currency'], limit_page_length=1) -%}
{%- set _dcur = _co[0].default_currency if _co else '' -%}
<style>
  .pt{font-family:'Segoe UI',-apple-system,Helvetica,Arial,sans-serif;color:#16202a;max-width:1060px;margin:0 auto;padding:0 20px 70px}
  .pt-hero{background:#0b6b3a;color:#fff;margin:0 -20px 26px;padding:34px 20px 30px}
  .pt-hero h1{margin:0 0 5px;font-size:26px}
  .pt-hero p{margin:0;color:#bfe0cd;font-size:15px}
  .pt-nav{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 26px}
  .pt-nav a{padding:8px 15px;border:1px solid #cfe3d7;border-radius:20px;font-size:13.5px;text-decoration:none;color:#0b6b3a;background:#fff}
  .pt-nav a.on{background:#0b6b3a;color:#fff;border-color:#0b6b3a}
  .pt-nav a:hover{text-decoration:none}
  .pt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px;margin:0 0 26px}
  .pt-card{border:1px solid #e3e8ec;border-radius:9px;padding:16px 18px;background:#fff}
  .pt-card .k{font-size:11.5px;letter-spacing:.7px;text-transform:uppercase;color:#8a94a0;margin:0 0 6px}
  .pt-card .v{font-size:21px;font-weight:700;color:#0b6b3a;margin:0}
  .pt-card .s{font-size:12.5px;color:#8a94a0;margin:4px 0 0}
  h2{font-size:18px;margin:30px 0 10px;padding-top:12px;border-top:2px solid #0b6b3a}
  table{width:100%;border-collapse:collapse;font-size:14px;margin:12px 0}
  th,td{text-align:left;padding:9px 10px;border-bottom:1px solid #e3e8ec}
  th{background:#fafbfc;font-size:11.5px;letter-spacing:.5px;text-transform:uppercase;color:#5a6773}
  td.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
  .pill{display:inline-block;padding:2px 10px;border-radius:14px;font-size:12px;font-weight:600}
  .pill-paid{background:#e8f5ee;color:#0b6b3a}
  .pill-due{background:#fdf7e8;color:#8a6100}
  .pill-open{background:#f2f7fb;color:#0d5a8f}
  .pt-msg{border:1px solid #e3e8ec;border-radius:9px;padding:26px;text-align:center;color:#5a6773;background:#fafbfc}
  .pt-msg a{color:#0b6b3a;font-weight:600}
  .pt-foot{margin-top:36px;padding-top:16px;border-top:1px solid #e3e8ec;font-size:12.5px;color:#8a94a0}
  .pt-home{display:flex;gap:20px;flex-wrap:wrap;align-items:stretch;border:1px solid #e3e8ec;border-radius:9px;overflow:hidden;background:#fff}
  .pt-home-img{width:320px;min-height:210px;background:#eef5f1;flex:0 0 auto}
  .pt-home-img img{width:100%;height:100%;object-fit:cover;display:block}
  .pt-home-body{flex:1 1 300px;padding:18px 20px 20px}
  .pt-home-body h3{margin:0 0 4px;font-size:19px;color:#0b6b3a}
  .pt-home-body .addr{margin:0 0 12px;font-size:13.5px;color:#5a6773}
  .pt-facts{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 12px}
  .pt-fact{background:#f4f8f6;border:1px solid #e0ebe5;border-radius:6px;padding:5px 10px;font-size:12.5px;color:#16202a}
  .pt-amen{margin:0;font-size:12.5px;color:#5a6773}
</style>

<div class="pt">
{% set me = frappe.session.user %}

{% if me == 'Guest' %}
  <div class="pt-hero"><h1>My Tenancy</h1><p>Sign in to see your tenancy.</p></div>
  <div class="pt-msg">Please <a href="/login?redirect-to=/my-tenancy">sign in</a> to view your tenancy details.</div>
{% else %}
  {% set tenants = frappe.get_all("Tenant", filters={"portal_user": me},
        fields=["name","tenant_name","email_id","mobile_no","customer"], limit_page_length=1) %}

  {% if not tenants %}
    <div class="pt-hero"><h1>My Tenancy</h1><p>No tenancy is linked to this login.</p></div>
    <div class="pt-msg">We could not find a tenancy for <b>{{ me }}</b>.<br>Please contact the letting office and quote this email address.</div>
  {% else %}
    {% set t = tenants[0] %}
    {% set leases = frappe.get_all("PS Lease Agreement",
          filters={"tenant": t.name, "docstatus": 1},
          fields=["name","property","property_unit","currency","rent_amount","payment_frequency",
                  "total_periodic_charges","security_deposit","deposit_status","start_date","end_date",
                  "lease_duration_months","notice_period_days","escalation_percentage",
                  "escalation_frequency","next_escalation_date"],
          order_by="start_date desc", limit_page_length=1) %}

    <div class="pt-hero">
      <h1>Hello, {{ (t.tenant_name or 'there').split(' ')[0] }}</h1>
      <p>Your tenancy, your payments and your maintenance requests, all in one place.</p>
    </div>

    <div class="pt-nav">
      <a class="on" href="/my-tenancy">My Tenancy</a>
      <a href="/my-invoices">Invoices &amp; Payments</a>
      <a href="/my-requests">Maintenance</a>
    </div>

    {% if not leases %}
      <div class="pt-msg">You have no active tenancy agreement on record.</div>
    {% else %}
      {% set lease = leases[0] %}
      {% set cur = lease.currency or _dcur %}
      {% set sched = frappe.get_all("PS Rent Schedule Item",
            filters={"parent": lease.name, "parenttype": "PS Lease Agreement"},
            fields=["period_label","due_date","rent_amount","other_charges","total_due",
                    "invoice_status","amount_paid","balance"],
            order_by="idx asc", limit_page_length=0) %}

      {% set props = frappe.get_all("PS Property", filters={"name": lease.property},
            fields=["name","property_name","address_line","suburb","city","region",
                    "ghana_post_gps","property_image","property_type","has_borehole",
                    "has_standby_generator","has_security","has_parking","has_elevator",
                    "has_swimming_pool","is_gated"], limit_page_length=1) %}
      {% set units = frappe.get_all("Property Unit", filters={"name": lease.property_unit},
            fields=["name","unit_number","unit_type","bedrooms","bathrooms","floor_area_sqm","floor"],
            limit_page_length=1) %}

      {% set ns = namespace(next_due=None, outstanding=0, paid=0) %}
      {% for r in sched %}
        {% if r.invoice_status != 'Paid' and r.invoice_status != 'Waived' %}
          {% if ns.next_due is none %}{% set ns.next_due = r %}{% endif %}
          {% set ns.outstanding = ns.outstanding + (r.balance or 0) %}
        {% else %}
          {% set ns.paid = ns.paid + (r.amount_paid or 0) %}
        {% endif %}
      {% endfor %}

      <div class="pt-grid">
        <div class="pt-card">
          <p class="k">Rent</p>
          <p class="v">{{ frappe.utils.fmt_money(lease.rent_amount, currency=cur) }}</p>
          <p class="s">per {{ (lease.payment_frequency or 'month')|lower }}{% if lease.total_periodic_charges %} &middot; plus {{ frappe.utils.fmt_money(lease.total_periodic_charges, currency=cur) }} charges{% endif %}</p>
        </div>
        <div class="pt-card">
          <p class="k">Next payment due</p>
          {% if ns.next_due %}
            <p class="v">{{ frappe.utils.fmt_money(ns.next_due.total_due, currency=cur) }}</p>
            <p class="s">{{ ns.next_due.period_label }} &middot; due {{ frappe.utils.formatdate(ns.next_due.due_date, "d MMM yyyy") }}</p>
          {% else %}
            <p class="v">Nothing due</p>
            <p class="s">You are fully paid up</p>
          {% endif %}
        </div>
        <div class="pt-card">
          <p class="k">Deposit held</p>
          <p class="v">{{ frappe.utils.fmt_money(lease.security_deposit, currency=cur) }}</p>
          <p class="s">Status: {{ lease.deposit_status or 'Held' }}</p>
        </div>
        <div class="pt-card">
          <p class="k">Tenancy ends</p>
          <p class="v" style="font-size:17px">{{ frappe.utils.formatdate(lease.end_date, "d MMM yyyy") }}</p>
          <p class="s">{{ lease.notice_period_days or 30 }} days notice required</p>
        </div>
      </div>

      <h2>Your home</h2>
      {% if props %}
        {% set pr = props[0] %}
        {% set un = units[0] if units else None %}
        {% set a = namespace(list=[]) %}
        {% if pr.is_gated %}{% set a.list = a.list + ['Gated estate'] %}{% endif %}
        {% if pr.has_security %}{% set a.list = a.list + ['24-hour security'] %}{% endif %}
        {% if pr.has_standby_generator %}{% set a.list = a.list + ['Standby generator'] %}{% endif %}
        {% if pr.has_borehole %}{% set a.list = a.list + ['Borehole water'] %}{% endif %}
        {% if pr.has_parking %}{% set a.list = a.list + ['Parking'] %}{% endif %}
        {% if pr.has_elevator %}{% set a.list = a.list + ['Lift'] %}{% endif %}
        {% if pr.has_swimming_pool %}{% set a.list = a.list + ['Swimming pool'] %}{% endif %}
        <div class="pt-home">
          <div class="pt-home-img">
            {% if pr.property_image %}<img src="{{ pr.property_image }}" alt="{{ pr.property_name }}">{% endif %}
          </div>
          <div class="pt-home-body">
            <h3>{{ pr.property_name }}</h3>
            <p class="addr">{% if un %}Unit {{ un.unit_number }} &middot; {% endif %}{{ pr.address_line or '' }}{% if pr.suburb %}, {{ pr.suburb }}{% endif %}{% if pr.city %}, {{ pr.city }}{% endif %}{% if pr.ghana_post_gps %} &middot; GhanaPost {{ pr.ghana_post_gps }}{% endif %}</p>
            <div class="pt-facts">
              {% if un and un.unit_type %}<span class="pt-fact">{{ un.unit_type }}</span>{% endif %}
              {% if un and un.bedrooms %}<span class="pt-fact">{{ un.bedrooms }} bedroom</span>{% endif %}
              {% if un and un.bathrooms %}<span class="pt-fact">{{ un.bathrooms }} bathroom</span>{% endif %}
              {% if un and un.floor_area_sqm %}<span class="pt-fact">{{ un.floor_area_sqm }} sqm</span>{% endif %}
              {% if un and un.floor %}<span class="pt-fact">{{ un.floor }} floor</span>{% endif %}
              {% if pr.property_type %}<span class="pt-fact">{{ pr.property_type }}</span>{% endif %}
            </div>
            {% if a.list %}<p class="pt-amen"><b>On site:</b> {{ a.list|join(' &middot; ') }}</p>{% endif %}
          </div>
        </div>
      {% endif %}

      <table>
        <tr><th style="width:35%">Property</th><td>{{ lease.property }}</td></tr>
        <tr><th>Unit</th><td>{{ lease.property_unit }}</td></tr>
        <tr><th>Agreement</th><td>{{ lease.name }}</td></tr>
        <tr><th>Term</th><td>{{ frappe.utils.formatdate(lease.start_date, "d MMM yyyy") }} to {{ frappe.utils.formatdate(lease.end_date, "d MMM yyyy") }} ({{ lease.lease_duration_months }} months)</td></tr>
        {% if lease.escalation_percentage %}<tr><th>Rent review</th><td>{{ lease.escalation_percentage }}% {{ (lease.escalation_frequency or '')|lower }}{% if lease.next_escalation_date %}, next on {{ frappe.utils.formatdate(lease.next_escalation_date, "d MMM yyyy") }}{% endif %}</td></tr>{% endif %}
        <tr><th>Registered contact</th><td>{{ t.email_id or '' }}{% if t.mobile_no %} &middot; {{ t.mobile_no }}{% endif %}</td></tr>
      </table>

      <h2>Your payment schedule</h2>
      <table>
        <thead><tr><th>Period</th><th>Due date</th><th class="n">Rent</th><th class="n">Charges</th><th class="n">Total</th><th>Status</th></tr></thead>
        <tbody>
        {% for r in sched %}
          <tr>
            <td>{{ r.period_label }}</td>
            <td>{{ frappe.utils.formatdate(r.due_date, "d MMM yyyy") }}</td>
            <td class="n">{{ frappe.utils.fmt_money(r.rent_amount, currency=cur) }}</td>
            <td class="n">{{ frappe.utils.fmt_money(r.other_charges, currency=cur) }}</td>
            <td class="n">{{ frappe.utils.fmt_money(r.total_due, currency=cur) }}</td>
            <td>{% if r.invoice_status == 'Paid' %}<span class="pill pill-paid">Paid</span>{% elif r.invoice_status == 'Invoiced' or r.invoice_status == 'Partly Paid' %}<span class="pill pill-due">{{ r.invoice_status }}</span>{% else %}<span class="pill pill-open">Upcoming</span>{% endif %}</td>
          </tr>
        {% endfor %}
        </tbody>
      </table>

    {% endif %}

    <div class="pt-foot">
      Managed by the letting office. If anything here looks wrong, contact the letting office.
    </div>
  {% endif %}
{% endif %}
</div>

