<div class="pt">
{% set me = frappe.session.user %}

{% if me == 'Guest' %}
  <div class="pt-hero"><h1>Invoices &amp; Payments</h1><p>Sign in to see your account.</p></div>
  <div class="pt-msg">Please <a href="/login?redirect-to=/my-invoices">sign in</a> to view your invoices.</div>
{% else %}
  {% set tenants = frappe.get_all("Tenant", filters={"portal_user": me},
        fields=["name","tenant_name","customer"], limit_page_length=1) %}

  {% if not tenants or not tenants[0].customer %}
    <div class="pt-hero"><h1>Invoices &amp; Payments</h1><p>No account is linked to this login.</p></div>
    <div class="pt-msg">We could not find a billing account for <b>{{ me }}</b>.<br>Please contact the letting office.</div>
  {% else %}
    {% set t = tenants[0] %}
    {% set invoices = frappe.get_all("Sales Invoice",
          filters={"customer": t.customer, "docstatus": 1},
          fields=["name","posting_date","due_date","currency","grand_total","outstanding_amount","status"],
          order_by="posting_date desc", limit_page_length=100) %}
    {% set payments = frappe.get_all("Payment Entry",
          filters={"party_type": "Customer", "party": t.customer, "docstatus": 1},
          fields=["name","posting_date","paid_amount","paid_from_account_currency","reference_no","mode_of_payment"],
          order_by="posting_date desc", limit_page_length=100) %}

    {% set ns = namespace(billed=0, owed=0, cur=_dcur) %}
    {% for i in invoices %}
      {% set ns.billed = ns.billed + (i.grand_total or 0) %}
      {% set ns.owed = ns.owed + (i.outstanding_amount or 0) %}
      {% set ns.cur = i.currency %}
    {% endfor %}

    <div class="pt-hero">
      <h1>Invoices &amp; Payments</h1>
      <p>Everything billed to you, and everything you have paid.</p>
    </div>

    <div class="pt-nav">
      <a href="/my-tenancy">My Tenancy</a>
      <a class="on" href="/my-invoices">Invoices &amp; Payments</a>
      <a href="/my-requests">Maintenance</a>
    </div>

    <div class="pt-grid">
      <div class="pt-card">
        <p class="k">Total billed</p>
        <p class="v">{{ frappe.utils.fmt_money(ns.billed, currency=ns.cur) }}</p>
      </div>
      <div class="pt-card">
        <p class="k">Currently outstanding</p>
        <p class="v {% if ns.owed > 0 %}warn{% endif %}">{{ frappe.utils.fmt_money(ns.owed, currency=ns.cur) }}</p>
      </div>
      <div class="pt-card">
        <p class="k">Invoices issued</p>
        <p class="v">{{ invoices|length }}</p>
      </div>
    </div>

    <h2>Invoices</h2>
    {% if invoices %}
    <table>
      <thead><tr><th>Invoice</th><th>Date</th><th>Due</th><th class="n">Amount</th><th class="n">Outstanding</th><th>Status</th></tr></thead>
      <tbody>
      {% for i in invoices %}
        <tr>
          <td>{{ i.name }}</td>
          <td>{{ frappe.utils.formatdate(i.posting_date, "d MMM yyyy") }}</td>
          <td>{{ frappe.utils.formatdate(i.due_date, "d MMM yyyy") }}</td>
          <td class="n">{{ frappe.utils.fmt_money(i.grand_total, currency=i.currency) }}</td>
          <td class="n">{{ frappe.utils.fmt_money(i.outstanding_amount, currency=i.currency) }}</td>
          <td>{% if i.status == 'Paid' %}<span class="pill pill-paid">Paid</span>{% elif i.status == 'Overdue' %}<span class="pill pill-over">Overdue</span>{% else %}<span class="pill pill-due">{{ i.status }}</span>{% endif %}</td>
        </tr>
      {% endfor %}
      </tbody>
    </table>
    {% else %}
      <div class="pt-msg">No invoices have been issued to you yet.</div>
    {% endif %}

    <h2>Payments received</h2>
    {% if payments %}
    <table>
      <thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th>Reference</th><th class="n">Amount</th></tr></thead>
      <tbody>
      {% for p in payments %}
        <tr>
          <td>{{ p.name }}</td>
          <td>{{ frappe.utils.formatdate(p.posting_date, "d MMM yyyy") }}</td>
          <td>{{ p.mode_of_payment or '—' }}</td>
          <td>{{ p.reference_no or '—' }}</td>
          <td class="n">{{ frappe.utils.fmt_money(p.paid_amount, currency=p.paid_from_account_currency) }}</td>
        </tr>
      {% endfor %}
      </tbody>
    </table>
    {% else %}
      <div class="pt-msg">No payments recorded against your account yet.</div>
    {% endif %}

    <div class="pt-foot">
      Managed by the letting office. For a copy of any invoice, contact the letting office quoting the invoice number.
    </div>
  {% endif %}
{% endif %}
</div>
